["Data/messages_es_game.dat", "Data/messages_game.dat"].each do |path|
  data = File.open(path, "rb") { |f| Marshal.load(f) }
  n_added = 0
  NAMES.each { |k, v| n_added += 1 if data[MOVE_NAMES].key?(k); data[MOVE_NAMES][k] = v }
  d_added = 0
  DESCS.each { |k, v| d_added += 1 if data[MOVE_DESCRIPTIONS].key?(k); data[MOVE_DESCRIPTIONS][k] = v }
  File.open(path, "wb") { |f| Marshal.dump(data, f) }
  puts "#{path}: nombres coincidentes=#{n_added}/#{NAMES.size}, descripciones coincidentes=#{d_added}/#{DESCS.size}"
end
